def find_test_demos_deep(path, max_depth=5):
    """Find test or demo related items recursively"""
    results = []

    def recurse(current_path, depth):
        if depth >= max_depth:
            return
        try:
            items = os.listdir(current_path)
            for item in items:
                p = os.path.join(current_path, item)
                if os.path.isdir(p):
                    results.append((p, f"{item}/"))
                    recurse(p, depth + 1)
                results.append((p, f"{item}"))
        except PermissionError:
            pass

    recurse(path, 0)
    return results

